import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.DYd_c05j.js";const u=JSON.parse('{"title":"Watchers","description":"","frontmatter":{},"headers":[],"relativePath":"watchers.md","filePath":"watchers.md","lastUpdated":null}'),n={name:"watchers.md"};function o(r,e,l,d,c,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="watchers" tabindex="-1">Watchers <a class="header-anchor" href="#watchers" aria-label="Permalink to &quot;Watchers&quot;">​</a></h1><p>Watchers are the first automatic detection layer for Homelab Console.</p><p>They are intentionally narrow:</p><ul><li>they only call read-only tools through <code>execute_tool</code>;</li><li>they do not run Claude or Codex;</li><li>they do not execute fixes;</li><li>they create tasks only through the Task Service;</li><li>they deduplicate open incidents before creating another task.</li><li>they keep task/incident history; watcher-created tasks are never deleted automatically.</li></ul><h2 id="current-watchers" tabindex="-1">Current Watchers <a class="header-anchor" href="#current-watchers" aria-label="Permalink to &quot;Current Watchers&quot;">​</a></h2><p><code>lab.alerts</code></p><ul><li>runs <code>lab.alerts.recent</code>;</li><li>owns only findings that do not have a dedicated watcher;</li><li>excludes UPS, Uptime Kuma and Cloudflare Tunnel findings, plus OPNsense gateway/WireGuard findings, so one condition has one incident owner;</li><li>reads warning/critical findings;</li><li>creates one task per new incident;</li><li>updates the existing open incident on repeated sightings.</li><li>keeps an operator-handled incident quiet on repeated sightings.</li><li>resolves open incidents only after their alert is missing for the configured grace period.</li></ul><p>The dedupe key is derived from the first stable finding field available: <code>dedupe_key</code>, <code>fingerprint</code>, <code>id</code>, or <code>code</code>.</p><p>If the finding has no stable key, the fallback key is derived from:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>watcher_id + provider_id + normalized message</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The fallback normalizes numeric counters so aggregate findings such as <code>193 unavailable entities</code> and <code>197 unavailable entities</code> update the same incident instead of creating a fresh task every run.</p><p><code>network.gateway</code></p><ul><li>runs <code>opnsense.gateways.status</code>;</li><li>maps only gateways declared in <code>providers.opnsense.gateway_observations</code>;</li><li>applies typed topology availability groups: in an <code>any</code> dual-WAN group one failed uplink is warning, while loss of every uplink is one critical group incident;</li><li>detects packet loss, high latency and high jitter as degraded gateway incidents;</li><li>supports per-uplink thresholds and <code>performance_monitoring: false</code> for a standby cellular gateway whose idle-path latency is not actionable;</li><li>does not emit a second performance incident for an offline gateway;</li><li>uses stable dedupe keys per gateway and failure type;</li><li>includes topology observation ids in incident payloads for exact UI attribution.</li></ul><p><code>network.wireguard</code></p><ul><li>runs <code>opnsense.wireguard.status</code>;</li><li>detects the case where no WireGuard peer is connected as critical;</li><li>detects stale peers as warning incidents;</li><li>uses stable dedupe keys per WireGuard failure type.</li></ul><p><code>network.zerotier</code></p><ul><li>runs <code>zerotier.members.list</code> against declared Central Legacy networks;</li><li>ignores stale laptops and phones unless they are explicitly declared in <code>required_online_member_ids</code>;</li><li>creates a warning when only part of the required set is available and a critical incident when no required member is online.</li></ul><p><code>cloudflare.tunnel</code></p><ul><li>runs the official control-plane <code>cloudflare.summary</code> tool;</li><li>owns tunnel availability, connector availability and reconnect findings;</li><li>emits at most one authoritative incident per run, ordered by impact;</li><li>does not infer public application availability, which remains owned by Uptime Kuma.</li></ul><p><code>uptimekuma.monitors</code></p><ul><li>runs <code>uptimekuma.monitors.status</code>;</li><li>ignores monitors that are up or in maintenance;</li><li>creates critical incidents for down monitors;</li><li>creates warning incidents for other non-healthy monitor states.</li></ul><p><code>power.ups</code></p><ul><li>runs <code>nutups.status</code>;</li><li>creates critical incidents when the UPS is on battery or low battery;</li><li>creates warning incidents for replace-battery/alarm state, low charge or runtime below 10 minutes;</li><li>uses stable dedupe keys per UPS and failure type;</li><li>resolves and auto-completes clean unclaimed watcher tasks when the UPS returns to online state.</li></ul><p><code>thermal.sensors</code></p><ul><li>runs only read-only temperature tools through the execution core: <code>nutups.status</code>, <code>opnsense.system.temperature</code>, <code>mikrotik.system.health</code>, <code>fritzbox.primary.temperature</code>, <code>fritzbox.secondary.temperature</code>, <code>proxmox.disks.temperatures</code>, <code>hosts.temperatures</code> and <code>frigate.stats</code>;</li><li>excludes room/ambient sensors and Home Assistant free-form discovery;</li><li>ignores FritzBox devices that report <code>supported=false</code>;</li><li>stores every canonical reading in the watcher run payload for later tuning;</li><li>creates incidents only when a reading crosses its category threshold;</li><li>uses stable dedupe keys per normalized sensor id.</li></ul><p>Initial thresholds are intentionally conservative:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ups: warning 38 C, critical 45 C</span></span>
<span class="line"><span>opnsense: warning 75 C, critical 85 C</span></span>
<span class="line"><span>mikrotik: warning 70 C, critical 80 C</span></span>
<span class="line"><span>fritzbox: warning 80 C, critical 90 C</span></span>
<span class="line"><span>disk: warning 55 C, critical 65 C</span></span>
<span class="line"><span>edge hosts (pizero/qdevice): warning 70 C, critical 80 C</span></span>
<span class="line"><span>compute hosts: warning 80 C, critical 90 C</span></span>
<span class="line"><span>frigate detectors: warning 75 C, critical 85 C</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><code>backup.freshness</code></p><ul><li>runs <code>proxmox.backups.list</code> and <code>pbs.backup.jobs.health</code>;</li><li>tolerates one missing source (for example no PBS): the run only errors when no backup source is readable, and per-tool errors stay in the run payload;</li><li>flags a guest whose latest vzdump backup is older than <code>providers.proxmox.backup_max_age_days</code> (default 3): warning above the threshold, critical above twice the threshold;</li><li>flags a PBS backup group whose latest snapshot is older than <code>providers.pbs.backup_group_max_age_days</code> with the same warning/critical split;</li><li>flags a guest listed in <code>required_backup_vmids</code> that has no visible backup;</li><li>ignores guests in <code>backup_ignore_vmids</code> and groups in <code>backup_ignore_groups</code> (<code>type/id</code> or <code>store:type/id</code>);</li><li>a guest that was never backed up and is not required stays silent: this watcher detects staleness, not backup policy;</li><li>uses stable dedupe keys per guest/group.</li></ul><p>PBS verification health is also included in <code>pbs.summary</code>, which feeds <code>lab.alerts</code>. A PBS installation with no verify jobs now produces the explicit <code>verify_jobs_missing</code> warning instead of appearing silently healthy. Verification does not replace a restore test; follow <code>docs/BACKUP_RESTORE_DRILL.md</code> for the operator-controlled restore drill.</p><p>This watcher exists because a backup that silently stops running produces no failed task and therefore no <code>lab.alerts</code> finding. Staleness is the only signal that catches &quot;the job never started&quot;.</p><p><code>security.certificates</code></p><ul><li>runs <code>network.tls.certificates</code> against the TLS targets declared in <code>tls.certificate_targets</code> (inventory only — callers cannot supply hosts);</li><li>warning when a certificate expires within <code>warning_days</code> (default 21), critical within <code>critical_days</code> (default 7) or already expired;</li><li>unreachable targets do not create incidents: availability stays owned by Uptime Kuma, and the probe result remains visible in the run payload;</li><li>uses stable dedupe keys per target id.</li></ul><p><code>storage.disks</code></p><ul><li>runs <code>proxmox.disks.temperatures</code> (which also reports SMART health and wearout);</li><li>creates a critical incident when a disk reports a SMART health value other than passed/ok/unknown;</li><li>stores every disk&#39;s health and wearout reading in the watcher run payload so wearout trends can be reviewed before any wearout threshold exists;</li><li>temperature thresholds remain owned by <code>thermal.sensors</code>;</li><li>uses stable dedupe keys per node and device path.</li></ul><p><code>network.presence</code></p><ul><li>runs <code>opnsense.devices.arp</code> and <code>opnsense.kea.leases</code>;</li><li>treats the first run as a baseline and does not create incidents from it;</li><li>detects new devices, duplicate hostnames and ARP-only devices on later runs.</li></ul><p>Presence detection is intentionally noisy compared to gateway and monitor health checks. Keep it manual unless the operator explicitly wants network inventory drift to create tasks.</p><h2 id="opnsense-direction" tabindex="-1">OPNsense Direction <a class="header-anchor" href="#opnsense-direction" aria-label="Permalink to &quot;OPNsense Direction&quot;">​</a></h2><p>The current OPNsense watcher flow is outbound polling from Homelab Console to OPNsense through narrowly scoped read-only tools. OPNsense does not call the API directly for watcher events.</p><p>The API currently exposes only these webhook-style routes:</p><ul><li>Telegram webhook: <code>POST /api/telegram/webhook</code>;</li><li>authenticated operator watcher routes under <code>/api/watchers/*</code>.</li></ul><p>If OPNsense needs to push events to Homelab Console later, add a dedicated typed endpoint with its own authentication and payload schema. Do not route it through a generic HTTP forwarder.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>Manual run:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/watchers/run</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>List open incidents:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/watchers/incidents</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>List recent watcher runs:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/watchers/runs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Read watcher scheduler/config state:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/watchers/status</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The response includes global scheduler state plus one row per watcher: <code>enabled</code>, <code>interval_seconds</code>, <code>min_severity</code>, <code>investigation_mode</code>, <code>last_run</code>, <code>next_run_at</code>, <code>last_error</code>, and <code>runbook_incident_type</code>.</p><p>Update the global scheduler state:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/watchers/automation</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The global value is persisted in <code>watcher_automation_state</code>, is shared by all API workers and survives restarts. <code>WATCHERS_ENABLED</code> is only the bootstrap default until the first persisted toggle is written.</p><p>Update one watcher at runtime:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PATCH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/watchers/config/{watcher_id}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;interval_seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;min_severity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;warning&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;investigation_mode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;manual&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>This state is persisted in the <code>watcher_configs</code> table. Missing rows fall back to the defaults from this document, so existing installs keep working after the migration.</p><p>Resolve an open incident that the operator confirms was already handled:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/watchers/incidents/{incident_id}/resolve-handled</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This marks the incident <code>resolved</code> with <code>resolution_reason=&quot;operator_already_handled&quot;</code>, appends a watcher-specific event/summary to the linked task, skips pending checks and completes the watcher-created task if it is not already final. If the same finding is seen again, the watcher updates the handled incident without creating another task. It preserves the audit trail instead of deleting stale watcher output.</p><p>All endpoints require operator auth. The run endpoint also requires CSRF.</p><h2 id="scheduler" tabindex="-1">Scheduler <a class="header-anchor" href="#scheduler" aria-label="Permalink to &quot;Scheduler&quot;">​</a></h2><p>Automatic scheduling is enabled by default and runs every 5 minutes.</p><div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WATCHERS_ENABLED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WATCHERS_INTERVAL_SECONDS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=300</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WATCHERS_MIN_SEVERITY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=warning</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WATCHERS_IGNORE_PATTERNS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WATCHERS_RESOLVE_AFTER_MISSING_RUNS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>When enabled, the API process starts a background scheduler after startup. The first run is delayed briefly, then repeats every <code>WATCHERS_INTERVAL_SECONDS</code> seconds, with a minimum interval of 60 seconds.</p><p>Watcher tasks are always created and audited. Local urgent critical incidents enter the notification outbox immediately; infrastructure critical incidents use a short debounce and cross-watcher aggregation based on the dependency graph. Warning incidents retain the longer debounce. Pending notifications are cancelled when their incidents clear, and cooldown and delivery history remain persistent. See <a href="./notifications">notifications.md</a>.</p><h2 id="already-handled-matching" tabindex="-1">Already-handled matching <a class="header-anchor" href="#already-handled-matching" aria-label="Permalink to &quot;Already-handled matching&quot;">​</a></h2><p>Before opening a new watcher task, the API compares the incident with recently resolved incidents. Exact dedupe-key matches are handled deterministically. Plausible semantic matches are narrowed to at most five candidates and sent to the configured task-router model for structured classification. High-confidence warning matches are linked to the previous task, marked <code>operator_already_handled</code>, flagged with <code>watcher.incident.auto_matched</code>, and do not create a new task or Telegram notification. Critical incidents are never auto-handled: they are flagged as <code>watcher.incident.possible_match</code> for operator review. Model calls are capped per hour and every decision records model, token usage, confidence, reason, and the matched incident in the audit trail.</p><div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INCIDENT_MATCHER_ENABLED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INCIDENT_MATCHER_MAX_CANDIDATES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=5</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INCIDENT_MATCHER_MAX_CALLS_PER_HOUR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=10</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INCIDENT_MATCHER_AUTO_HANDLE_CONFIDENCE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=0.9</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>The default enabled watcher set is currently:</p><ul><li><code>cloudflare.tunnel</code>;</li><li><code>lab.alerts</code>;</li><li><code>network.gateway</code>;</li><li><code>network.wireguard</code>;</li><li><code>network.zerotier</code>;</li><li><code>power.ups</code>;</li><li><code>uptimekuma.monitors</code>.</li></ul><p>Available but not scheduled by default:</p><ul><li><code>backup.freshness</code>;</li><li><code>network.presence</code>;</li><li><code>security.certificates</code>;</li><li><code>storage.disks</code>;</li><li><code>thermal.sensors</code>.</li></ul><p>Keep <code>network.presence</code> manual unless inventory drift should create tasks automatically. Keep <code>thermal.sensors</code> manual until the operator has reviewed a day or two of real readings and confirmed the canonical sensor list. Thermal provider failures are recorded in the run payload and never clear that provider&#39;s existing incidents; a run with no readable thermal provider fails closed. Enable <code>backup.freshness</code> after aligning <code>backup_max_age_days</code> / <code>backup_group_max_age_days</code> with the lab&#39;s real backup schedule, so the first scheduled run does not flag guests that are simply on a weekly cadence. Enable <code>security.certificates</code> after declaring <code>tls.certificate_targets</code> (with no targets the watcher is a no-op). <code>storage.disks</code> has an unambiguous signal (SMART failure) and can be enabled as soon as one manual run confirms the disk list looks right. Provider-specific noise is configured structurally in inventory: known stopped Proxmox VMIDs, Home Assistant count thresholds, required ZeroTier members and per-uplink gateway thresholds remain visible as metrics while only actionable conditions become findings.</p><p><code>WATCHERS_MIN_SEVERITY=critical</code> creates new incidents only for critical findings. An already-open warning that is still observed remains open and is marked <code>policy_state=filtered</code>; it is not falsely resolved as <code>alert_cleared</code>. <code>WATCHERS_IGNORE_PATTERNS</code> is a comma-separated case-insensitive substring list matched against provider id, severity and finding text, with the same observed-versus-filtered behavior.</p><p>Each watcher can override <code>enabled</code>, <code>interval_seconds</code>, <code>min_severity</code>, and <code>investigation_mode</code> through the UI/API. The default mode is <code>manual</code>. <code>auto_investigate</code> is a read-only dispatch gate, not remediation: it accepts only new deterministic warning incidents with a known runbook and a Task Router decision for the OpenCode-powered <code>fixer</code> agent with confidence of at least 0.80 and no operator dependency. Only one worker task may be active; rejected or unreachable delivery releases the task back to the manual queue through the canonical state machine. Manual runs with explicit watcher ids still run that watcher on demand; scheduled/background runs use the enabled set and each watcher&#39;s own interval.</p><h2 id="test-flow" tabindex="-1">Test Flow <a class="header-anchor" href="#test-flow" aria-label="Permalink to &quot;Test Flow&quot;">​</a></h2><ol><li>For deterministic manual testing, disable automation through <code>POST /api/watchers/automation</code> (or set <code>WATCHERS_ENABLED=false</code> before the first persisted toggle exists).</li><li>Start API and web normally.</li><li>Log in to the web UI.</li><li>Trigger <code>POST /api/watchers/run</code>.</li><li>Check <code>GET /api/watchers/incidents</code>.</li><li>Check <code>/api/tasks</code> for any created watcher tasks.</li><li>In the web Watchers app, switch between Open/Resolved/All and use the task button on an incident to open the linked task.</li></ol><p>The created tasks have <code>source=&quot;watcher&quot;</code> and <code>created_by=&quot;service:watcher&quot;</code>. When <code>TASK_ROUTER_ENABLED=true</code>, a new watcher task queues asynchronous routing and is later enriched with a redacted <code>task.router_decision</code> event. That event may suggest category, priority, owner, labels, dedupe/runbook hints and first read-only steps, but it does not claim the task or execute remediation. Incidents whose alert disappears are not resolved immediately. Each successful watcher run that does not see the alert increments <code>missing_runs</code> and sets <code>last_missing_at</code>; the incident is marked <code>resolved</code> with <code>resolution_reason=&quot;alert_cleared&quot;</code> after <code>WATCHERS_RESOLVE_AFTER_MISSING_RUNS</code> missed runs. The default is <code>3</code>, so one clean sample does not close an incident/task during a brief flap. If the alert returns before that threshold, the existing incident/task is reused and the clearing counter is reset.</p><p>When an alert clears, the watcher may also auto-complete the linked task, but only when it is still a clean watcher task:</p><ul><li><code>source=&quot;watcher&quot;</code>;</li><li><code>created_by=&quot;service:watcher&quot;</code>;</li><li>status is still <code>open</code>;</li><li>no assigned agent and no claim timestamp;</li><li>no other open incident is linked to the same task.</li></ul><p>Pending task checks are skipped with a watcher-specific reason, the summary is updated with the auto-resolution note, a <code>watcher.task.auto_completed</code> event is appended, and a <code>TaskResolution</code> snapshot is kept. The task remains technically unassigned, but task API responses expose <code>resolution_label=&quot;auto_closed&quot;</code> and <code>auto_closed=true</code> so the UI can label it as <code>Auto closed</code> instead of ordinary <code>Unassigned</code>. Claimed or manually worked tasks are left open for the assigned agent/operator.</p><p>Incident rows expose <code>dedupe_note</code>, <code>dedupe_basis</code>, <code>auto_close_note</code>, and <code>runbook_incident_type</code> so the UI can show whether a run created a new task, updated an existing task, linked to a root incident, or is waiting through the auto-close grace period.</p><p>Open incidents are protected by a partial unique index on <code>dedupe_key</code> where <code>status=&#39;open&#39;</code>. The service also uses a PostgreSQL advisory transaction lock per watcher id to avoid duplicate scheduler work across workers; the unique index is the final data-level guard.</p><h2 id="out-of-scope" tabindex="-1">Out Of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out Of Scope&quot;">​</a></h2><ul><li>no automatic remediation;</li><li>no shell/SSH/HTTP generic execution;</li><li>no Agent Runner;</li><li>no incident escalation engine;</li><li>no multi-agent dispatch.</li></ul>`,88)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
